MingusParser::MingusParser(TokenStream *input) : MingusParser(input, antlr4::atn::ParserATNSimulatorOptions()) {}

MingusParser::MingusParser(TokenStream *input, const antlr4::atn::ParserATNSimulatorOptions &options) : Parser(input) {
  MingusParser::initialize();
  _interpreter = new atn::ParserATNSimulator(this, *mingusparserParserStaticData->atn, mingusparserParserStaticData->decisionToDFA, mingusparserParserStaticData->sharedContextCache, options);
}

MingusParser::~MingusParser() {
  delete _interpreter;
}

const atn::ATN& MingusParser::getATN() const {
  return *mingusparserParserStaticData->atn;
}

std::string MingusParser::getGrammarFileName() const {
  return "MingusParser.g4";
}

const std::vector<std::string>& MingusParser::getRuleNames() const {
  return mingusparserParserStaticData->ruleNames;
}

const dfa::Vocabulary& MingusParser::getVocabulary() const {
  return mingusparserParserStaticData->vocabulary;
}

antlr4::atn::SerializedATNView MingusParser::getSerializedATN() const {
  return mingusparserParserStaticData->serializedATN;
}


//----------------- ProgramContext ------------------------------------------------------------------

MingusParser::ProgramContext::ProgramContext(ParserRuleContext *parent, size_t invokingState)
  : ParserRuleContext(parent, invokingState) {
}

tree::TerminalNode* MingusParser::ProgramContext::EOF() {
  return getToken(MingusParser::EOF, 0);
}

std::vector<MingusParser::ModuleContext *> MingusParser::ProgramContext::module() {
  return getRuleContexts<MingusParser::ModuleContext>();
}

MingusParser::ModuleContext* MingusParser::ProgramContext::module(size_t i) {
  return getRuleContext<MingusParser::ModuleContext>(i);
}


size_t MingusParser::ProgramContext::getRuleIndex() const {
  return MingusParser::RuleProgram;
}

void MingusParser::ProgramContext::enterRule(tree::ParseTreeListener *listener) {
  auto parserListener = dynamic_cast<MingusParserListener *>(listener);
  if (parserListener != nullptr)
    parserListener->enterProgram(this);
}

void MingusParser::ProgramContext::exitRule(tree::ParseTreeListener *listener) {
  auto parserListener = dynamic_cast<MingusParserListener *>(listener);
  if (parserListener != nullptr)
    parserListener->exitProgram(this);
}


std::any MingusParser::ProgramContext::accept(tree::ParseTreeVisitor *visitor) {
  if (auto parserVisitor = dynamic_cast<MingusParserVisitor*>(visitor))
    return parserVisitor->visitProgram(this);
  else
    return visitor->visitChildren(this);
}

